  1 | import { useCallback, useRef } from "react";
  2 | import jsmediatags from "jsmediatags";
  3 | import type { Track } from "../types";
  4 | 
  5 | export interface MetadataResult {
  6 |   title?: string;
  7 |   artist?: string;
  8 |   album?: string;
  9 |   coverUrl?: string;
 10 |   duration: number;
 11 | }
 12 | 
 13 | const BATCH_SIZE = 5;
 14 | const INITIAL_PRIORITY_COUNT = 10;
 15 | 
 16 | /**
 17 |  * Hook para extrair metadados (ID3 tags) de arquivos de áudio.
 18 |  * Usa lazy loading: processa em lotes para não travar a UI.
 19 |  */
 20 | export function useMetadata() {
 21 |   const coverUrlsRef = useRef<Map<string, string>>(new Map());
 22 | 
 23 |   /**
 24 |    * Extrai metadados de um arquivo de áudio.
 25 |    * Retorna um objeto com title, artist, album, coverUrl e duration.
 26 |    */
 27 |   const extractMetadata = useCallback(
 28 |     (file: File): Promise<MetadataResult> => {
 29 |       return new Promise((resolve) => {
 30 |         // Fallback: usar nome do arquivo se não conseguir ler tags
 31 |         const fallback: MetadataResult = {
 32 |           title: file.name.replace(/\.[^/.]+$/, ""),
 33 |           duration: 0,
 34 |         };
 35 | 
 36 |         // Só tenta ler tags para formatos suportados
 37 |         const supportedTypes = ["audio/mpeg", "audio/mp3", "audio/flac", "audio/ogg", "audio/wav"];
 38 |         if (!supportedTypes.includes(file.type)) {
 39 |           resolve(fallback);
 40 |           return;
 41 |         }
 42 | 
 43 |         jsmediatags.read(file, {
 44 |           onSuccess: (data) => {
 45 |             const tags = data.tags;
 46 |             let coverUrl: string | undefined;
 47 | 
 48 |             // Converte a capa do álbum (se existir) para data URL
 49 |             if (tags.picture) {
 50 |               const { data: pictureData, format } = tags.picture;
 51 |               const base64 = arrayBufferToBase64(pictureData);
 52 |               const mimeType = format || "image/jpeg";
 53 |               coverUrl = `data:${mimeType};base64,${base64}`;
 54 | 
 55 |               // Armazena para evitar recriação
 56 |               const key = file.name + file.size;
 57 |               coverUrlsRef.current.set(key, coverUrl);
 58 |             }
 59 | 
 60 |             resolve({
 61 |               title: tags.title || fallback.title,
 62 |               artist: tags.artist,
 63 |               album: tags.album,
 64 |               coverUrl,
 65 |               duration: tags.duration ?? 0,
 66 |             });
 67 |           },
 68 |           onError: () => {
 69 |             // Se falhar, usa o fallback
 70 |             resolve(fallback);
 71 |           },
 72 |         });
 73 |       });
 74 |     },
 75 |     []
 76 |   );
 77 | 
 78 |   /**
 79 |    * Processa uma lista de arquivos com lazy loading (batches).
 80 |    *
 81 |    * Os primeiros INITIAL_PRIORITY_COUNT arquivos são processados imediatamente
 82 |    * para que o usuário veja resultados rápido. O restante é processado em lotes
 83 |    * de BATCH_SIZE com yields (setTimeout 0) para não travar a UI.
 84 |    *
 85 |    * @param files - Lista de arquivos de áudio
 86 |    * @param onProgress - Callback opcional para reportar progresso { processed, total }
 87 |    */
 88 |   const processFiles = useCallback(
 89 |     async (
 90 |       files: File[],
 91 |       onProgress?: (progress: { processed: number; total: number }) => void
 92 |     ): Promise<Track[]> => {
 93 |       const tracks: Track[] = [];
 94 |       const now = Date.now();
 95 | 
 96 |       const processOne = async (i: number): Promise<Track> => {
 97 |         const file = files[i];
 98 |         const url = URL.createObjectURL(file);
 99 |         const metadata = await extractMetadata(file);
100 | 
101 |         return {
102 |           id: `local-${now}-${i}`,
103 |           title: metadata.title || file.name.replace(/\.[^/.]+$/, ""),
104 |           artist: metadata.artist,
105 |           album: metadata.album,
106 |           duration: metadata.duration,
107 |           coverUrl: metadata.coverUrl,
108 |           src: url,
109 |         };
110 |       };
111 | 
112 |       // Fase 1: Processa os primeiros N arquivos imediatamente (prioridade)
113 |       const priorityCount = Math.min(INITIAL_PRIORITY_COUNT, files.length);
114 |       for (let i = 0; i < priorityCount; i++) {
115 |         const track = await processOne(i);
116 |         tracks.push(track);
117 |         onProgress?.({ processed: i + 1, total: files.length });
118 |       }
119 | 
120 |       // Fase 2: Processa o restante em lotes, cedendo a thread para a UI
121 |       for (let i = priorityCount; i < files.length; i += BATCH_SIZE) {
122 |         // Yield para a UI poder renderizar
123 |         await new Promise((resolve) => setTimeout(resolve, 0));
124 | 
125 |         const batch = files.slice(i, i + BATCH_SIZE);
126 |         const batchResults = await Promise.all(
127 |           batch.map((_, batchIndex) => processOne(i + batchIndex))
128 |         );
129 |         tracks.push(...batchResults);
130 | 
131 |         onProgress?.({ processed: Math.min(i + BATCH_SIZE, files.length), total: files.length });
132 |       }
133 | 
134 |       return tracks;
135 |     },
136 |     [extractMetadata]
137 |   );
138 | 
139 |   /**
140 |    * Libera URLs de capas do álbum para evitar vazamento de memória.
141 |    */
142 |   const cleanupCoverUrls = useCallback(() => {
143 |     coverUrlsRef.current.clear();
144 |   }, []);
145 | 
146 |   return {
147 |     extractMetadata,
148 |     processFiles,
149 |     cleanupCoverUrls,
150 |   };
151 | }
152 | 
153 | function arrayBufferToBase64(buffer: ArrayBuffer): string {
154 |   const bytes = new Uint8Array(buffer);
155 |   let binary = "";
156 |   for (let i = 0; i < bytes.length; i++) {
157 |     binary += String.fromCharCode(bytes[i]);
158 |   }
159 |   return btoa(binary);
160 | }
